SELECT fp.id, fp.title, fp.content, fp.user_id, u.username, u.avatar, fp.scenic_id, fp.route_id, fp.view_count, fp.reply_count, fp.is_top, fp.is_essence, fp.is_audit, fp.create_time FROM forum_post fp LEFT JOIN user u ON fp.user_id = u.id
fp.deleted = 0
AND fp.title LIKE CONCAT('%', #{query.title}, '%')
AND fp.user_id = #{query.userId}
AND fp.scenic_id = #{query.scenicId}
AND fp.route_id = #{query.routeId}
AND fp.is_audit = #{query.isAudit}
ORDER BY fp.is_top DESC, fp.create_time DESC
